using System.Collections;using UnityEngine;using UnityEngine.UI;using UnityEngine.SceneManagement;public class SceneTransition : MonoBehaviour{    [SerializeField] private Image faderImage;    [SerializeField] private float fadeDuration = 1.0f;    private static SceneTransition instance;    private void Awake()    {        if (instance == null)        {            instance = this;            DontDestroyOnLoad(gameObject);        }        else        {            Destroy(gameObject);            return;        }    }    private void Start()    {        StartCoroutine(FadeOut());        SwitchScene("Game");    }    public void SwitchScene(string sceneName)    {        StartCoroutine(TransitionRoutine(sceneName));    }    private IEnumerator TransitionRoutine(string sceneName)    {        yield return StartCoroutine(FadeIn());        AsyncOperation asyncLoad = SceneManager.LoadSceneAsync(sceneName);        while (!asyncLoad.isDone)        {            yield return null;        }        yield return StartCoroutine(FadeOut());    }    private IEnumerator FadeIn()    {        float elapsedTime = 0f;        Color color = faderImage.color;        while (elapsedTime < fadeDuration)        {            elapsedTime += Time.deltaTime;            color.a = Mathf.Clamp01(elapsedTime / fadeDuration);            faderImage.color = color;            yield return null;        }    }    private IEnumerator FadeOut()    {        float elapsedTime = 0f;        Color color = faderImage.color;        while (elapsedTime < fadeDuration)        {            elapsedTime += Time.deltaTime;            color.a = Mathf.Clamp01(1f - (elapsedTime / fadeDuration));            faderImage.color = color;            yield return null;        }    }}